function run_q5_procedure_cohort_estimation_contrast(phase_key,subject_numbers)
% Q5 Procedure n=30 estimation and high-intrinsic minus low-intrinsic contrast.
if nargin<1,phase_key="procedure";end;if nargin<2,subject_numbers=1:30;end;phase_key=lower(string(phase_key));subject_numbers=subject_numbers(:)';repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');root=fullfile(repo,'results',sprintf('q5_intrinsic_%s',phase_key),'cohort_specification');addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));Slog=table();
for sn=subject_numbers,sid=sprintf('subject%03d',sn);if ismember(sn,[1 2 10]),df=fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1',sid,sprintf('%s_nirs_data.mat',sid));else,df=fullfile(fl,'nirs_spm_inputs',sid,sprintf('%s_nirs_data.mat',sid));end;D=load(df,'nirs_data');nch=D.nirs_data.nch;clear D;M=readtable(fullfile(fl,'nirs_spm_inputs',sid,sprintf('%s_channel_metadata.csv',sid)),'TextType','string');
for hb=["HbO","HbR"],sf=fullfile(root,sid,char(hb),sprintf('SPM_indiv_%s.mat',hb));L=load(sf,'SPM_nirs');A=L.SPM_nirs;if ~isfield(A.nirs,'step')||~strcmpi(string(A.nirs.step),'estimation'),nirs_spm_estimation_batch_fixed(sf,df);L=load(sf,'SPM_nirs');A=L.SPM_nirs;end;B=double(A.nirs.beta);assert(isequal(size(B),[5 nch]));N=string(A.xX.name(:));if phase_key=="procedure",targets=["LILEProcedure","HILEProcedure","LIHEProcedure","HIHEProcedure"];elseif phase_key=="dom",targets=["LILEDOM","HILEDOM","LIHEDOM","HIHEDOM"];else,targets=["LILEAOE","HILEAOE","LIHEAOE","HIHEAOE"];end;k=zeros(4,1);for i=1:4,k(i)=find(contains(N,targets(i)),1);end;c=zeros(5,1);c(k)=[-.5 .5 -.5 .5];rss=double(A.nirs.ResSS);if ~isvector(rss),rss=diag(rss)';end;dof=double(A.xX.erdf);b=c'*B;se=sqrt(max((c'*double(A.xX.Bcov)*c).*(rss./dof),0));t=b./se;p=betainc(dof./(dof+t.^2),dof/2,.5);q=bh(p);R=table(repmat(string(sid),nch,1),repmat(hb,nch,1),(1:nch)',string(M.channel_id),string(M.channel_type),string(M.roi),string(M.laterality),b(:),se(:),t(:),p(:),q(:),'VariableNames',{'subject_id','hemoglobin','channel_index','channel_id','channel_type','roi','laterality','contrast_beta','contrast_se','contrast_t','contrast_p_two_sided','contrast_q_bh61'});writetable(R,fullfile(root,sid,sprintf('%s_%s_q5_high_intrinsic_minus_low_intrinsic_%s_channel_contrasts.csv',sid,hb,phase_key)));Slog=[Slog;table(string(sid),hb,dof,sum(q<.05),'VariableNames',{'subject_id','hemoglobin','effective_df','n_q_bh61_lt_005'})];end,end
writetable(Slog,fullfile(root,sprintf('q5_%s_estimation_contrast_n30.csv',phase_key)));end
function q=bh(p),q=nan(size(p));v=isfinite(p);pv=p(v);[s,o]=sort(pv(:));m=numel(s);z=min(1,flipud(cummin(flipud(s.*m./(1:m)'))));zv=zeros(size(pv));zv(o)=z;q(v)=zv;end
